// ── 13. Orchestrator-prompt → delegation → Composio round-trip ────
//
// End-to-end test that ties together the three things the user needs
// confidence in:
//
//   1. The orchestrator's system prompt (built by
//      `orchestrator::prompt::build`) advertises a connected toolkit
//      via the collapsed `delegate_to_integrations_agent` tool.
//   2. Given that prompt and a user task that mentions the toolkit,
//      the LLM (mocked) emits a tool call that satisfies the real
//      `SkillDelegationTool` schema.
//   3. Delegation reaches the integrations side, where a
//      `ComposioActionTool` is dispatched against a real
//      `ComposioClient` pointed at a hermetic fake backend — and the
//      backend records the action with the orchestrator-provided args.
//
// To avoid pulling in the full sub-agent runner, the test substitutes
// a `TestDelegationTool` that mirrors `SkillDelegationTool`'s contract
// (same tool name, same schema validation against the connected
// toolkit list) but runs a *nested* `run_tool_call_loop` for the
// integrations side instead of calling `dispatch_subagent`. The
// nested loop is the same code path the real integrations_agent uses,
// so the wiring under test is the orchestrator → delegation arg →
// integrations LLM → ComposioActionTool → backend chain.

struct TestDelegationTool {
    connected_toolkits: Vec<(String, String)>,
    nested_tools: Arc<parking_lot::Mutex<Option<Vec<Box<dyn Tool>>>>>,
    inner_provider: Arc<KeywordScriptedProvider>,
}

impl TestDelegationTool {
    fn new(
        connected_toolkits: Vec<(String, String)>,
        nested_tools: Vec<Box<dyn Tool>>,
        inner_provider: Arc<KeywordScriptedProvider>,
    ) -> Self {
        Self {
            connected_toolkits,
            nested_tools: Arc::new(parking_lot::Mutex::new(Some(nested_tools))),
            inner_provider,
        }
    }
}

#[async_trait]
impl Tool for TestDelegationTool {
    fn name(&self) -> &str {
        // Mirror SkillDelegationTool's canonical name so the orchestrator
        // system prompt's references resolve.
        "delegate_to_integrations_agent"
    }
    fn description(&self) -> &str {
        "Delegate to integrations_agent (test stand-in for SkillDelegationTool)."
    }
    fn parameters_schema(&self) -> serde_json::Value {
        // Same shape as the real SkillDelegationTool.
        let slugs: Vec<&str> = self
            .connected_toolkits
            .iter()
            .map(|(s, _)| s.as_str())
            .collect();
        json!({
            "type": "object",
            "required": ["toolkit", "prompt"],
            "properties": {
                "toolkit": {"type": "string", "enum": slugs},
                "prompt": {"type": "string"}
            }
        })
    }
    async fn execute(&self, args: serde_json::Value) -> anyhow::Result<ToolResult> {
        let toolkit = args
            .get("toolkit")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .trim()
            .to_string();
        let prompt = args
            .get("prompt")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .trim()
            .to_string();
        if toolkit.is_empty() {
            return Ok(ToolResult::error("`toolkit` is required"));
        }
        let known = self
            .connected_toolkits
            .iter()
            .any(|(slug, _)| slug == &toolkit);
        if !known {
            return Ok(ToolResult::error(format!(
                "toolkit `{toolkit}` is not connected"
            )));
        }
        if prompt.is_empty() {
            return Ok(ToolResult::error("`prompt` is required"));
        }

        // Take ownership of the nested tool list (one-shot).
        let nested_tools = self
            .nested_tools
            .lock()
            .take()
            .expect("nested tools already consumed");

        // Run a NESTED tool loop — same code path the integrations_agent
        // uses inside the real sub-agent runner.
        let mut nested_history = vec![ChatMessage::user(format!("[toolkit={toolkit}] {prompt}"))];
        let out = run_tool_call_loop(
            self.inner_provider.as_ref(),
            &mut nested_history,
            &nested_tools,
            "test-integrations",
            "test-model",
            0.0,
            true,
            None,
            "channel",
            &mm(),
            5,
            None,
            None,
            &[],
            None,
            None,
        )
        .await?;

        Ok(ToolResult::success(out))
    }
}

#[tokio::test]
async fn orchestrator_prompt_drives_composio_call_via_delegation_chain() {
    use crate::openhuman::agent::agents::orchestrator::prompt as orch_prompt;
    use crate::openhuman::agent::prompts::types::ConnectedIntegration;
    use crate::openhuman::composio::ComposioActionTool;

    // ── 1. Build the orchestrator's system prompt with gmail wired in.
    let integrations = vec![ConnectedIntegration {
        toolkit: "gmail".into(),
        description: "Email send/fetch via Gmail.".into(),
        tools: Vec::new(),
        connected: true,
    }];
    let ctx = {
        use crate::openhuman::context::prompt::{LearnedContextData, ToolCallFormat};
        use std::collections::HashSet;
        use std::sync::OnceLock;
        static EMPTY: OnceLock<HashSet<String>> = OnceLock::new();
        crate::openhuman::context::prompt::PromptContext {
            workspace_dir: std::path::Path::new("."),
            model_name: "test",
            agent_id: "orchestrator",
            tools: &[],
            skills: &[],
            dispatcher_instructions: "",
            learned: LearnedContextData::default(),
            visible_tool_names: EMPTY.get_or_init(HashSet::new),
            tool_call_format: ToolCallFormat::PFormat,
            connected_integrations: &integrations,
            connected_identities_md: String::new(),
            include_profile: false,
            include_memory_md: false,
            curated_snapshot: None,
            user_identity: None,
        }
    };
    let system_prompt = orch_prompt::build(&ctx).expect("build orchestrator prompt");
    // The prompt must explicitly route gmail tasks via the collapsed
    // delegation tool — otherwise the orchestrator can't know to call it.
    assert!(system_prompt.contains("## Connected Integrations"));
    assert!(system_prompt.contains("delegate_to_integrations_agent"));
    assert!(system_prompt.contains("toolkit: \"gmail\""));

    // ── 2. Spawn the fake Composio backend + wire a ComposioActionTool.
    let backend = spawn_fake_composio_backend(ComposioFixture::realistic()).await;
    let composio_client = backend.client();
    let gmail_action_tool: Box<dyn Tool> = Box::new(ComposioActionTool::new(
        composio_client,
        "GMAIL_SEND_EMAIL".to_string(),
        "Send a Gmail email".to_string(),
        Some(json!({"type": "object"})),
    ));

    // ── 3. Inner (integrations-side) provider: emit a ComposioActionTool call,
    // then a final reply once it sees the action's success marker.
    let inner_provider = Arc::new(KeywordScriptedProvider::new(vec![
        KeywordRule::tool_call(
            "toolkit=gmail",
            ScriptedToolCall::new(
                "GMAIL_SEND_EMAIL",
                json!({
                    "recipient_email": "alice@example.com",
                    "subject": "hi",
                    "body": "hello from orchestrator",
                }),
            ),
        ),
        KeywordRule::final_reply("gmail-msg-1234", "delivered"),
    ]));

    let nested_tools: Vec<Box<dyn Tool>> = vec![gmail_action_tool];

    // ── 4. Outer (orchestrator) provider: when the user asks to email Alice
    // via gmail, emit the delegation tool call. After the delegation
    // returns "delivered", produce the final user-facing reply.
    let outer_provider = KeywordScriptedProvider::new(vec![
        KeywordRule::tool_call(
            "send an email to alice",
            ScriptedToolCall::new(
                "delegate_to_integrations_agent",
                json!({
                    "toolkit": "gmail",
                    "prompt": "Send an email to alice@example.com saying hi"
                }),
            ),
        ),
        KeywordRule::final_reply("delivered", "I've sent the email to Alice."),
    ]);

    // ── 5. Wire the test delegation tool that bridges outer -> inner loop.
    let delegation_tool: Box<dyn Tool> = Box::new(TestDelegationTool::new(
        vec![(
            "gmail".to_string(),
            "Email send/fetch via Gmail.".to_string(),
        )],
        nested_tools,
        inner_provider.clone(),
    ));
    let outer_tools: Vec<Box<dyn Tool>> = vec![delegation_tool];

    let mut history = vec![
        ChatMessage::system(system_prompt),
        ChatMessage::user("Please send an email to alice@example.com saying hi via gmail."),
    ];

    // ── 6. Drive the outer (orchestrator) loop.
    let final_reply = run_tool_call_loop(
        &outer_provider,
        &mut history,
        &outer_tools,
        "orchestrator-mock",
        "test-model",
        0.0,
        true,
        None,
        "channel",
        &mm(),
        5,
        None,
        None,
        &[],
        None,
        None,
    )
    .await
    .expect("orchestrator loop should complete");

    assert_eq!(final_reply, "I've sent the email to Alice.");

    // ── 7. Assert the Composio backend actually received the action with
    // the orchestrator-routed arguments.
    let backend_reqs = backend.requests();
    let exec = backend_reqs
        .iter()
        .find(|(m, p, _)| m == "POST" && p == "/execute")
        .expect("Composio /execute must have been called via the orchestrator chain");
    assert_eq!(exec.2["tool"], "GMAIL_SEND_EMAIL");
    assert_eq!(exec.2["arguments"]["recipient_email"], "alice@example.com");
    assert_eq!(exec.2["arguments"]["subject"], "hi");

    // ── 8. Both sides of the chain should have seen exactly one turn that
    // emitted the expected call.
    let outer_turns = outer_provider.turns();
    assert!(
        outer_turns
            .iter()
            .any(|t| t.rule_keyword.as_deref() == Some("send an email to alice")),
        "orchestrator must have matched the delegation rule"
    );
    let inner_turns = inner_provider.turns();
    assert!(
        inner_turns
            .iter()
            .any(|t| t.rule_keyword.as_deref() == Some("toolkit=gmail")),
        "integrations agent must have matched its tool-call rule"
    );
}

//! Smart-mock test support for the agent harness.
//!
//! This module provides a reusable "fake LLM" that drives the real
//! [`run_tool_call_loop`] without needing any network access. Two
//! building blocks are exposed:
//!
//! 1. [`KeywordScriptedProvider`] — a [`Provider`] implementation that
//!    inspects the latest `user` message of the conversation and emits
//!    canned tool calls (or a final reply) when a configured keyword
//!    matches. The first turn that has *no* matching rule returns a
//!    plain "done" reply, which terminates the loop deterministically.
//!
//!    Compared to the hand-rolled `ScriptedProvider` in
//!    [`super::tool_loop_tests`], this provider:
//!      * Reacts to the rolling conversation state instead of replaying
//!        a fixed queue — so tests can exercise iterative loops where
//!        what the LLM does next depends on what tools returned.
//!      * Supports both **native** OpenAI-style `tool_calls` and
//!        **prompt-guided** `<tool_call>…</tool_call>` text — flipping
//!        a single flag toggles which surface the harness exercises.
//!      * Records the messages it saw and the responses it returned for
//!        post-hoc assertion.
//!
//! 2. [`spawn_fake_composio_backend`] — boots a minimal axum app that
//!    responds to the `/agent-integrations/composio/*` routes with
//!    realistic-looking fixture data (real-world toolkit/action shapes,
//!    not synthetic gibberish). Tests can pair this with a
//!    [`crate::openhuman::composio::ComposioClient`] to exercise the
//!    full agent → tool → backend → response flow against a hermetic
//!    in-process server.
//!
//! Both helpers are `#[cfg(test)]`-only so they never leak into release
//! binaries.

use std::collections::VecDeque;
use std::sync::Arc;

use async_trait::async_trait;
use parking_lot::Mutex;
use serde_json::json;

use crate::openhuman::providers::traits::ProviderCapabilities;
use crate::openhuman::providers::{ChatMessage, ChatRequest, ChatResponse, Provider, ToolCall};

/// One scripted reaction the [`KeywordScriptedProvider`] can emit when
/// it sees its keyword in the latest user/tool turn.
#[derive(Debug, Clone)]
pub struct KeywordRule {
    /// Substring matched (case-insensitive) against the latest user
    /// or tool message in the conversation.
    pub keyword: String,
    /// Tool calls to emit. Empty ⇒ no tool calls, only `final_text`.
    pub tool_calls: Vec<ScriptedToolCall>,
    /// Optional plain-text body to include alongside any tool calls.
    /// When `tool_calls` is empty, this becomes the loop-terminating
    /// final response.
    pub final_text: Option<String>,
    /// How many times this rule may fire. `None` ⇒ unlimited.
    pub max_fires: Option<usize>,
}

#[derive(Debug, Clone)]
pub struct ScriptedToolCall {
    pub name: String,
    pub arguments: serde_json::Value,
}

impl ScriptedToolCall {
    pub fn new(name: impl Into<String>, arguments: serde_json::Value) -> Self {
        Self {
            name: name.into(),
            arguments,
        }
    }
}

impl KeywordRule {
    pub fn final_reply(keyword: impl Into<String>, text: impl Into<String>) -> Self {
        Self {
            keyword: keyword.into(),
            tool_calls: Vec::new(),
            final_text: Some(text.into()),
            max_fires: None,
        }
    }

    pub fn tool_call(keyword: impl Into<String>, call: ScriptedToolCall) -> Self {
        Self {
            keyword: keyword.into(),
            tool_calls: vec![call],
            final_text: None,
            max_fires: Some(1),
        }
    }

    pub fn with_text(mut self, text: impl Into<String>) -> Self {
        self.final_text = Some(text.into());
        self
    }

    pub fn unlimited(mut self) -> Self {
        self.max_fires = None;
        self
    }
}

/// Snapshot of one turn the provider served — handy for tests that
/// want to assert what the LLM "saw" without coupling to the harness
/// internals.
#[derive(Debug, Clone)]
pub struct ProviderTurn {
    pub messages: Vec<ChatMessage>,
    pub rule_keyword: Option<String>,
    pub emitted_tool_calls: Vec<ToolCall>,
    pub emitted_text: Option<String>,
}

struct ProviderState {
    rules: Vec<KeywordRule>,
    fired: Vec<usize>,
    turns: Vec<ProviderTurn>,
    fallback_text: String,
    next_call_id: usize,
    /// Optional queue of scripted responses to consume *before* the
    /// keyword rules run — useful when a test wants the first turn to
    /// behave deterministically regardless of the user message.
    forced: VecDeque<ChatResponse>,
}

/// Smart provider that reacts to conversation state via keyword rules.
pub struct KeywordScriptedProvider {
    state: Arc<Mutex<ProviderState>>,
    native_tools: bool,
    vision: bool,
}

impl KeywordScriptedProvider {
    pub fn new(rules: Vec<KeywordRule>) -> Self {
        Self {
            state: Arc::new(Mutex::new(ProviderState {
                rules,
                fired: Vec::new(),
                turns: Vec::new(),
                fallback_text: "done".to_string(),
                next_call_id: 0,
                forced: VecDeque::new(),
            })),
            native_tools: false,
            vision: false,
        }
    }

    pub fn with_native_tools(mut self, enabled: bool) -> Self {
        self.native_tools = enabled;
        self
    }

    pub fn with_vision(mut self, enabled: bool) -> Self {
        self.vision = enabled;
        self
    }

    pub fn with_fallback(self, text: impl Into<String>) -> Self {
        {
            let mut guard = self.state.lock();
            guard.fallback_text = text.into();
        }
        self
    }

    pub fn push_forced_response(&self, resp: ChatResponse) {
        self.state.lock().forced.push_back(resp);
    }

    pub fn turns(&self) -> Vec<ProviderTurn> {
        self.state.lock().turns.clone()
    }

    pub fn turn_count(&self) -> usize {
        self.state.lock().turns.len()
    }
}

fn latest_user_or_tool_msg(messages: &[ChatMessage]) -> Option<&ChatMessage> {
    messages
        .iter()
        .rev()
        .find(|m| m.role == "user" || m.role == "tool")
}

#[async_trait]
impl Provider for KeywordScriptedProvider {
    fn capabilities(&self) -> ProviderCapabilities {
        ProviderCapabilities {
            native_tool_calling: self.native_tools,
            vision: self.vision,
        }
    }

    async fn chat_with_system(
        &self,
        _system_prompt: Option<&str>,
        _message: &str,
        _model: &str,
        _temperature: f64,
    ) -> anyhow::Result<String> {
        Ok("fallback".into())
    }

    async fn chat(
        &self,
        request: ChatRequest<'_>,
        _model: &str,
        _temperature: f64,
    ) -> anyhow::Result<ChatResponse> {
        let messages = request.messages.to_vec();
        let mut state = self.state.lock();

        // Forced queue wins, regardless of keyword matching.
        if let Some(resp) = state.forced.pop_front() {
            state.turns.push(ProviderTurn {
                messages,
                rule_keyword: None,
                emitted_tool_calls: resp.tool_calls.clone(),
                emitted_text: resp.text.clone(),
            });
            return Ok(resp);
        }

        let probe = latest_user_or_tool_msg(&messages)
            .map(|m| m.content.to_lowercase())
            .unwrap_or_default();

        let mut chosen: Option<usize> = None;
        for (idx, rule) in state.rules.iter().enumerate() {
            let fired = *state.fired.get(idx).unwrap_or(&0);
            if let Some(cap) = rule.max_fires {
                if fired >= cap {
                    continue;
                }
            }
            if probe.contains(&rule.keyword.to_lowercase()) {
                chosen = Some(idx);
                break;
            }
        }

        let (rule_keyword, tool_calls, text) = if let Some(idx) = chosen {
            while state.fired.len() <= idx {
                state.fired.push(0);
            }
            state.fired[idx] += 1;
            let rule = state.rules[idx].clone();
            let tool_calls: Vec<ToolCall> = if self.native_tools {
                rule.tool_calls
                    .iter()
                    .map(|c| {
                        let id = state.next_call_id;
                        state.next_call_id += 1;
                        ToolCall {
                            id: format!("call_{id}"),
                            name: c.name.clone(),
                            arguments: c.arguments.to_string(),
                        }
                    })
                    .collect()
            } else {
                Vec::new()
            };

            let text = if self.native_tools {
                rule.final_text.clone()
            } else if !rule.tool_calls.is_empty() {
                // Prompt-guided: emit XML-wrapped tool calls in text.
                let mut body = String::new();
                if let Some(prefix) = &rule.final_text {
                    body.push_str(prefix);
                    if !prefix.ends_with('\n') {
                        body.push('\n');
                    }
                }
                for c in &rule.tool_calls {
                    body.push_str("<tool_call>");
                    body.push_str(&json!({"name": c.name, "arguments": c.arguments}).to_string());
                    body.push_str("</tool_call>\n");
                }
                Some(body)
            } else {
                rule.final_text.clone()
            };

            (Some(rule.keyword.clone()), tool_calls, text)
        } else {
            // No rule matched — emit the fallback as the final reply
            // so the loop terminates rather than hanging.
            (None, Vec::new(), Some(state.fallback_text.clone()))
        };

        let resp = ChatResponse {
            text: text.clone(),
            tool_calls: tool_calls.clone(),
            usage: None,
        };

        state.turns.push(ProviderTurn {
            messages,
            rule_keyword,
            emitted_tool_calls: tool_calls,
            emitted_text: text,
        });

        Ok(resp)
    }
}

