import { json, setCors } from "../http.mjs";
import {
  behavior,
  getDelayMs,
  getMockUser,
  MOCK_JWT,
  sleep,
} from "../state.mjs";

export async function handleAuth(ctx) {
  const { method, url, res, origin } = ctx;
  const mockBehavior = behavior();

  if (
    method === "POST" &&
    /^\/telegram\/login-tokens\/[^/]+\/consume\/?$/.test(url)
  ) {
    if (mockBehavior.token === "expired") {
      json(res, 401, { success: false, error: "Token expired or invalid" });
      return true;
    }
    if (mockBehavior.token === "invalid") {
      json(res, 401, { success: false, error: "Invalid token" });
      return true;
    }
    const jwt = mockBehavior.jwt ? `${MOCK_JWT}-${mockBehavior.jwt}` : MOCK_JWT;
    json(res, 200, { success: true, data: { jwtToken: jwt } });
    return true;
  }

  if (method === "POST" && /^\/auth\/desktop-exchange\/?$/.test(url)) {
    json(res, 200, {
      sessionToken: "mock-session-token",
      user: { id: "user-123", firstName: "Test", username: "testuser" },
    });
    return true;
  }

  if (
    method === "GET" &&
    (/^\/telegram\/me\/?(\?.*)?$/.test(url) ||
      /^\/auth\/me\/?(\?.*)?$/.test(url))
  ) {
    const delayMs = getDelayMs("telegramMeDelayMs");
    if (delayMs > 0) {
      await sleep(delayMs);
    }
    if (mockBehavior.telegramMeStatus) {
      const status = Number(mockBehavior.telegramMeStatus) || 500;
      json(res, status, {
        success: false,
        error: mockBehavior.telegramMeError || "Mock telegram/me failure",
      });
      return true;
    }
    if (mockBehavior.session === "revoked") {
      json(res, 401, { success: false, error: "Unauthorized" });
      return true;
    }
    json(res, 200, { success: true, data: getMockUser() });
    return true;
  }

  if (method === "GET" && /^\/auth\/integrations\/?(\?.*)?$/.test(url)) {
    json(res, 200, { success: true, data: [] });
    return true;
  }

  if (method === "POST" && /^\/auth\/email\/send-link\/?$/.test(url)) {
    // Gap fill: passwordless magic-link send. Always succeed in mock.
    json(res, 200, {
      success: true,
      data: { sent: true, expiresAt: new Date(Date.now() + 600000).toISOString() },
    });
    return true;
  }

  if (method === "GET" && /^\/auth\/[^/]+\/login\/?(\?.*)?$/.test(url)) {
    const redirectUrl = `${origin}/mock-oauth`;
    if (url.includes("responseType=json")) {
      json(res, 200, { success: true, data: { oauthUrl: redirectUrl } });
      return true;
    }
    setCors(res);
    res.writeHead(302, { Location: redirectUrl });
    res.end();
    return true;
  }

  if (method === "GET" && /^\/auth\/telegram\/connect\/?(\?.*)?$/.test(url)) {
    if (mockBehavior.telegramDuplicate === "true") {
      json(res, 409, {
        success: false,
        error: "Telegram account already linked to another user",
      });
      return true;
    }
    json(res, 200, {
      success: true,
      data: { oauthUrl: `${origin}/mock-telegram-oauth` },
    });
    return true;
  }

  if (method === "GET" && /^\/auth\/notion\/connect\/?(\?.*)?$/.test(url)) {
    if (mockBehavior.notionTokenRevoked === "true") {
      json(res, 401, { success: false, error: "OAuth token has been revoked" });
      return true;
    }
    const workspace = mockBehavior.notionWorkspace || "Test User's Workspace";
    json(res, 200, {
      success: true,
      data: { oauthUrl: `${origin}/mock-notion-oauth`, workspace },
    });
    return true;
  }

  if (method === "GET" && /^\/auth\/google\/connect\/?(\?.*)?$/.test(url)) {
    if (mockBehavior.gmailTokenRevoked === "true") {
      json(res, 401, { success: false, error: "OAuth token has been revoked" });
      return true;
    }
    if (mockBehavior.gmailTokenExpired === "true") {
      json(res, 401, { success: false, error: "OAuth token has expired" });
      return true;
    }
    json(res, 200, {
      success: true,
      data: { oauthUrl: `${origin}/mock-google-oauth` },
    });
    return true;
  }

  if (method === "POST" && /^\/auth\/telegram\/?$/.test(url)) {
    // Gap fill: telegram login callback exchange.
    json(res, 200, { success: true, data: { jwtToken: MOCK_JWT } });
    return true;
  }

  // /mock-oauth, /mock-oauth/<provider>, and the legacy
  // /mock-<provider>-oauth aliases are handled by routes/oauth.mjs, which
  // actually completes the OAuth flow via deep links.

  return false;
}

import { html, json, setCors } from "../http.mjs";
import { behavior, MOCK_JWT } from "../state.mjs";

/**
 * Mock OAuth provider landing page + callback handlers.
 *
 * The real flow looks like:
 *   1. App calls `GET /auth/<provider>/connect` → backend returns `oauthUrl`
 *      pointing at the actual provider (Google, Notion, Slack, …).
 *   2. App opens that URL in the system browser.
 *   3. User logs in at the provider, provider redirects back to the backend
 *      callback, the backend exchanges the code and finally redirects to the
 *      desktop deep link `openhuman://oauth/success?integrationId=…&provider=…`
 *      (see app/src/utils/desktopDeepLinkListener.ts).
 *   4. The Tauri shell receives the deep link, the app marks the integration
 *      connected.
 *
 * For e2e we collapse all of that into local HTTP. `/auth/<provider>/connect`
 * already points the app at `${origin}/mock-<provider>-oauth`; this module
 * makes that page actually finish the dance by issuing the deep link.
 *
 * Behavior knobs (via `setMockBehavior`):
 *   oauthAutoRedirectMs       — delay before the deep-link redirect fires
 *                                (default 50). Set `manual` to require a click.
 *   oauthIntegrationId        — integrationId param in the success deep link
 *                                (default `mock-<provider>-integration`).
 *   oauthForceError           — when "true", redirect to the error deep link.
 *   oauthErrorCode            — error code passed to the error deep link.
 *
 * Query-string overrides (per request, win over behavior knobs):
 *   ?provider=<name>          — overrides provider inferred from the path.
 *   ?integrationId=<id>       — overrides the integrationId emitted.
 *   ?manual=1                 — disable auto-redirect (test wants to click).
 *   ?error=<code>             — emit an error deep link instead of success.
 */
export function handleOAuth(ctx) {
  const { method, url, parsedBody, res } = ctx;

  // /mock-oauth/<provider> and the legacy /mock-<provider>-oauth aliases.
  const newStyle = url.match(/^\/mock-oauth\/([a-z][a-z0-9_-]*)\/?(\?.*)?$/i);
  const legacy = url.match(
    /^\/mock-(telegram|notion|google|gmail|slack|discord|twitter|github)-oauth\/?(\?.*)?$/i,
  );
  const legacyGeneric = !newStyle && !legacy && /^\/mock-oauth\/?(\?.*)?$/.test(url);

  if (method === "GET" && (newStyle || legacy || legacyGeneric)) {
    const provider = newStyle?.[1] || legacy?.[1] || "generic";
    const params = parseQuery(url);
    const mockBehavior = behavior();
    const integrationId =
      params.integrationId ||
      mockBehavior.oauthIntegrationId ||
      `mock-${provider}-integration`;
    const errorCode =
      params.error ||
      (mockBehavior.oauthForceError === "true"
        ? mockBehavior.oauthErrorCode || "access_denied"
        : null);
    const manual =
      params.manual === "1" || mockBehavior.oauthAutoRedirectMs === "manual";
    const autoRedirectMs = manual
      ? null
      : clampDelay(mockBehavior.oauthAutoRedirectMs, 50);

    const target = errorCode
      ? `openhuman://oauth/error?provider=${encodeURIComponent(
          params.provider || provider,
        )}&error=${encodeURIComponent(errorCode)}`
      : `openhuman://oauth/success?integrationId=${encodeURIComponent(
          integrationId,
        )}&provider=${encodeURIComponent(params.provider || provider)}`;

    html(res, 200, renderOAuthPage({ provider, target, autoRedirectMs, errorCode }));
    return true;
  }

  // Generic callback exchange. Real providers each hit their own
  // backend-specific URL; for e2e a single endpoint per provider that
  // always returns a session token is enough.
  const callbackMatch = url.match(/^\/auth\/([a-z][a-z0-9_-]*)\/callback\/?(\?.*)?$/i);
  if (method === "GET" && callbackMatch) {
    const provider = callbackMatch[1];
    const params = parseQuery(url);
    const mockBehavior = behavior();

    if (mockBehavior.oauthForceError === "true" || params.error) {
      const errorCode =
        params.error || mockBehavior.oauthErrorCode || "access_denied";
      // Redirect to the desktop error deep link.
      setCors(res);
      res.writeHead(302, {
        Location: `openhuman://oauth/error?provider=${encodeURIComponent(
          provider,
        )}&error=${encodeURIComponent(errorCode)}`,
      });
      res.end();
      return true;
    }

    const integrationId =
      params.integrationId ||
      mockBehavior.oauthIntegrationId ||
      `mock-${provider}-integration`;
    setCors(res);
    res.writeHead(302, {
      Location: `openhuman://oauth/success?integrationId=${encodeURIComponent(
        integrationId,
      )}&provider=${encodeURIComponent(provider)}`,
    });
    res.end();
    return true;
  }

  // Backend-style code-for-token POST exchange, in case any provider
  // routes through the desktop app rather than the deep link.
  if (
    method === "POST" &&
    /^\/auth\/[a-z][a-z0-9_-]*\/exchange\/?$/i.test(url)
  ) {
    const provider = url.split("/")[2] ?? "generic";
    const mockBehavior = behavior();
    if (mockBehavior.oauthForceError === "true") {
      json(res, 400, {
        success: false,
        error: mockBehavior.oauthErrorCode || "access_denied",
      });
      return true;
    }
    const integrationId =
      parsedBody?.integrationId ||
      mockBehavior.oauthIntegrationId ||
      `mock-${provider}-integration`;
    json(res, 200, {
      success: true,
      data: {
        provider,
        integrationId,
        sessionToken: "mock-session-token",
        jwtToken: MOCK_JWT,
      },
    });
    return true;
  }

  return false;
}

function parseQuery(url) {
  const qIndex = url.indexOf("?");
  if (qIndex < 0) return {};
  const out = {};
  const search = url.slice(qIndex + 1);
  for (const pair of search.split("&")) {
    if (!pair) continue;
    const eq = pair.indexOf("=");
    const key = eq < 0 ? pair : pair.slice(0, eq);
    const raw = eq < 0 ? "" : pair.slice(eq + 1);
    try {
      out[decodeURIComponent(key)] = decodeURIComponent(raw.replace(/\+/g, " "));
    } catch {
      out[key] = raw;
    }
  }
  return out;
}

function clampDelay(raw, fallback) {
  const parsed = Number(raw);
  if (!Number.isFinite(parsed) || parsed < 0) return fallback;
  return Math.min(parsed, 30000);
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;",
  })[c]);
}

function renderOAuthPage({ provider, target, autoRedirectMs, errorCode }) {
  const safeTarget = escapeHtml(target);
  const safeProvider = escapeHtml(provider);
  const heading = errorCode
    ? `${safeProvider} — sign-in failed (${escapeHtml(errorCode)})`
    : `${safeProvider} — mock sign-in`;
  const blurb = errorCode
    ? "This mock provider is simulating a failed OAuth. The desktop app should receive an error deep link."
    : "This is the mock OAuth provider. The desktop app should receive a success deep link.";

  const autoRedirectScript =
    autoRedirectMs === null
      ? ""
      : `<script>setTimeout(function(){window.location.href=${JSON.stringify(
          target,
        )};}, ${Number(autoRedirectMs)});</script>`;

  const metaRefresh =
    autoRedirectMs === null
      ? ""
      : `<meta http-equiv="refresh" content="${(Number(autoRedirectMs) /
          1000).toFixed(2)};url=${safeTarget}" />`;

  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <title>Mock OAuth · ${safeProvider}</title>
  ${metaRefresh}
  <style>
    body { font: 16px/1.4 system-ui, sans-serif; max-width: 480px; margin: 80px auto; padding: 0 24px; color: #1d1d1d; }
    h1 { font-size: 20px; margin: 0 0 12px; }
    p  { margin: 0 0 16px; color: #555; }
    a.button { display: inline-block; padding: 10px 16px; background: #4A83DD; color: #fff; border-radius: 8px; text-decoration: none; font-weight: 600; }
    code { background: #f3f3f3; padding: 2px 6px; border-radius: 4px; font-size: 13px; }
  </style>
</head>
<body>
  <h1>${heading}</h1>
  <p>${blurb}</p>
  <p>Target: <code>${safeTarget}</code></p>
  <p><a class="button" id="continue" href="${safeTarget}">Continue to OpenHuman</a></p>
  ${autoRedirectScript}
</body>
</html>`;
}

import { json } from "../http.mjs";
import { behavior } from "../state.mjs";

export function handlePayments(ctx) {
  const { method, url, parsedBody, res } = ctx;
  const mockBehavior = behavior();

  if (method === "GET" && /^\/payments\/credits\/balance\/?(\?.*)?$/.test(url)) {
    json(res, 200, {
      success: true,
      data: { balanceUsd: 10, topUpBalanceUsd: 0, topUpBaselineUsd: 0 },
    });
    return true;
  }

  if (
    method === "GET" &&
    (/^\/payments\/plan\/?(\?.*)?$/.test(url) ||
      /^\/payments\/stripe\/currentPlan\/?(\?.*)?$/.test(url))
  ) {
    const plan = mockBehavior.plan || "FREE";
    const isActive = mockBehavior.planActive === "true";
    const periodEnd = new Date(Date.now() + 30 * 86400000).toISOString();
    json(res, 200, {
      success: true,
      data: {
        plan,
        hasActiveSubscription: isActive,
        planExpiry: isActive ? periodEnd : null,
        subscription: isActive
          ? { id: "sub_mock_1", status: "active", currentPeriodEnd: periodEnd }
          : null,
      },
    });
    return true;
  }

  if (
    method === "POST" &&
    (/^\/payments\/stripe\/checkout\/?$/.test(url) ||
      /^\/payments\/stripe\/purchasePlan\/?$/.test(url))
  ) {
    if (mockBehavior.purchaseError === "true") {
      json(res, 500, { success: false, error: "Payment service unavailable" });
      return true;
    }
    json(res, 200, {
      success: true,
      data: {
        sessionId: "cs_mock_" + Date.now(),
        checkoutUrl: null,
      },
    });
    return true;
  }

  if (method === "POST" && /^\/payments\/stripe\/portal\/?$/.test(url)) {
    json(res, 200, {
      success: true,
      data: { portalUrl: "https://billing.stripe.com/mock-portal" },
    });
    return true;
  }

  if (method === "POST" && /^\/payments\/coinbase\/charge\/?$/.test(url)) {
    if (mockBehavior.coinbaseError === "true") {
      json(res, 500, { success: false, error: "Coinbase service unavailable" });
      return true;
    }
    json(res, 200, {
      success: true,
      data: {
        gatewayTransactionId: "charge_mock_" + Date.now(),
        hostedUrl: "https://commerce.coinbase.com/mock-charge",
        status: "NEW",
        expiresAt: new Date(Date.now() + 3600000).toISOString(),
      },
    });
    return true;
  }

  if (method === "POST" && /^\/payments\/purchase\/?$/.test(url)) {
    const plan = parsedBody?.plan || mockBehavior.plan || "BASIC";
    json(res, 200, {
      success: true,
      data: {
        sessionId: "cs_mock_" + Date.now(),
        url: "https://checkout.stripe.com/mock-purchase",
        plan,
      },
    });
    return true;
  }

  if (
    method === "GET" &&
    /^\/payments\/credits\/auto-recharge\/?(\?.*)?$/.test(url)
  ) {
    json(res, 200, {
      success: true,
      data: {
        enabled: false,
        thresholdUsd: 5,
        rechargeAmountUsd: 10,
        weeklyLimitUsd: 50,
        spentThisWeekUsd: 0,
        weekStartDate: new Date().toISOString(),
        inFlight: false,
        hasSavedPaymentMethod: false,
        lastTriggeredAt: null,
        lastRechargeAt: null,
      },
    });
    return true;
  }

  if (
    method === "PATCH" &&
    /^\/payments\/credits\/auto-recharge\/?$/.test(url)
  ) {
    // Gap fill: update auto-recharge config. Echo back the patched values.
    json(res, 200, {
      success: true,
      data: {
        enabled: parsedBody?.enabled ?? false,
        thresholdUsd: parsedBody?.thresholdUsd ?? 5,
        rechargeAmountUsd: parsedBody?.rechargeAmountUsd ?? 10,
        weeklyLimitUsd: parsedBody?.weeklyLimitUsd ?? 50,
        spentThisWeekUsd: 0,
        weekStartDate: new Date().toISOString(),
        inFlight: false,
        hasSavedPaymentMethod: false,
        lastTriggeredAt: null,
        lastRechargeAt: null,
      },
    });
    return true;
  }

  if (method === "GET" && /^\/payments\/cards\/?(\?.*)?$/.test(url)) {
    json(res, 200, { success: true, data: { cards: [], defaultCardId: null } });
    return true;
  }

  if (
    method === "GET" &&
    /^\/payments\/credits\/auto-recharge\/cards\/?(\?.*)?$/.test(url)
  ) {
    json(res, 200, { success: true, data: { cards: [], defaultCardId: null } });
    return true;
  }

  // ── Gap fills ─────────────────────────────────────────────────────

  if (
    method === "POST" &&
    /^\/payments\/credits\/auto-recharge\/cards\/setup-intent\/?$/.test(url)
  ) {
    json(res, 200, {
      success: true,
      data: {
        clientSecret: "seti_mock_" + Date.now() + "_secret_mock",
        setupIntentId: "seti_mock_" + Date.now(),
      },
    });
    return true;
  }

  if (
    method === "DELETE" &&
    /^\/payments\/credits\/auto-recharge\/cards\/[^/]+\/?$/.test(url)
  ) {
    json(res, 200, { success: true, data: { deleted: true } });
    return true;
  }

  if (
    method === "GET" &&
    /^\/payments\/credits\/transactions\/?(\?.*)?$/.test(url)
  ) {
    json(res, 200, {
      success: true,
      data: {
        transactions: [],
        nextCursor: null,
      },
    });
    return true;
  }

  if (method === "POST" && /^\/payments\/credits\/top-up\/?$/.test(url)) {
    // Don't collapse an explicit 0 into the default — `Number(0) || 10` is
    // a classic falsy-coalesce bug. Use Number.isFinite so any non-numeric
    // body still falls back to 10.
    const rawAmount = parsedBody?.amountUsd;
    const parsedAmount = rawAmount == null ? 10 : Number(rawAmount);
    const amount =
      Number.isFinite(parsedAmount) && parsedAmount >= 0 ? parsedAmount : 10;
    json(res, 200, {
      success: true,
      data: {
        sessionId: "cs_mock_topup_" + Date.now(),
        checkoutUrl: null,
        amountUsd: amount,
      },
    });
    return true;
  }

  if (
    method === "GET" &&
    /^\/payments\/coinbase\/charge\/[^/]+\/?(\?.*)?$/.test(url)
  ) {
    const status = mockBehavior.cryptoStatus || "NEW";
    json(res, 200, {
      success: true,
      data: {
        status,
        payment: {
          status,
          amountPaid:
            status === "UNDERPAID"
              ? "150.00"
              : status === "OVERPAID"
                ? "350.00"
                : "250.00",
          amountExpected: "250.00",
          currency: "USDC",
          underpaidAmount: mockBehavior.cryptoUnderpaidAmount || "0",
          overpaidAmount: mockBehavior.cryptoOverpaidAmount || "0",
        },
        expiresAt: new Date(Date.now() + 3600000).toISOString(),
      },
    });
    return true;
  }

  if (method === "GET" && /^\/billing\/current-plan\/?(\?.*)?$/.test(url)) {
    const plan = mockBehavior.plan || "FREE";
    const isActive = mockBehavior.planActive === "true";
    const expiry = mockBehavior.planExpiry || null;
    json(res, 200, {
      success: true,
      data: {
        plan,
        hasActiveSubscription: isActive,
        planExpiry: expiry,
        subscription: isActive
          ? {
              id: "sub_mock_123",
              status: "active",
              currentPeriodEnd:
                expiry || new Date(Date.now() + 30 * 86400000).toISOString(),
            }
          : null,
      },
    });
    return true;
  }

  return false;
}

export type ComposerSendBlockReason =
  | 'empty_input'
  | 'missing_thread'
  | 'composer_blocked'
  | 'usage_limit_reached'
  | 'socket_disconnected';

export type SlashCommandDecision =
  | { kind: 'new_or_clear'; blockedByWelcomeLock: boolean }
  | { kind: 'not_handled' };

export interface ComposerSendDecisionArgs {
  rawText: string;
  selectedThreadId: string | null;
  composerInteractionBlocked: boolean;
  isAtLimit: boolean;
  socketStatus: string;
}

export interface ComposerSendDecision {
  shouldSend: boolean;
  trimmedText: string;
  blockReason?: ComposerSendBlockReason;
}

export interface ComposerBlockedSendFeedback {
  showLimitModal: boolean;
  error: { code: 'usage_limit_reached' | 'socket_disconnected'; message: string };
}

export const handleComposerSlashCommand = (
  command: string,
  welcomeLocked: boolean
): SlashCommandDecision => {
  const cmd = command.toLowerCase();
  if (cmd === '/new' || cmd === '/clear') {
    return { kind: 'new_or_clear', blockedByWelcomeLock: welcomeLocked };
  }
  return { kind: 'not_handled' };
};

export const evaluateComposerSend = (args: ComposerSendDecisionArgs): ComposerSendDecision => {
  const trimmedText = args.rawText.trim();

  if (!trimmedText) {
    return { shouldSend: false, trimmedText, blockReason: 'empty_input' };
  }

  if (!args.selectedThreadId) {
    return { shouldSend: false, trimmedText, blockReason: 'missing_thread' };
  }

  if (args.composerInteractionBlocked) {
    return { shouldSend: false, trimmedText, blockReason: 'composer_blocked' };
  }

  if (args.isAtLimit) {
    return { shouldSend: false, trimmedText, blockReason: 'usage_limit_reached' };
  }

  if (args.socketStatus !== 'connected') {
    return { shouldSend: false, trimmedText, blockReason: 'socket_disconnected' };
  }

  return { shouldSend: true, trimmedText };
};

export const getComposerBlockedSendFeedback = (
  blockReason: ComposerSendBlockReason | undefined
): ComposerBlockedSendFeedback | null => {
  if (blockReason === 'usage_limit_reached') {
    return {
      showLimitModal: true,
      error: {
        code: 'usage_limit_reached',
        message: 'Usage limit reached. Upgrade or wait for reset.',
      },
    };
  }

  if (blockReason === 'socket_disconnected') {
    return {
      showLimitModal: false,
      error: {
        code: 'socket_disconnected',
        message:
          'Realtime socket is not connected — responses cannot be delivered without a client ID.',
      },
    };
  }

  return null;
};

use serde::{Deserialize, Serialize};

/// User session information
#[allow(dead_code)]
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Session {
    /// JWT session token
    pub token: String,
    /// User ID
    pub user_id: String,
    /// When the session was created (Unix timestamp)
    pub created_at: u64,
    /// When the session expires (Unix timestamp)
    pub expires_at: Option<u64>,
}

/// User profile information
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct User {
    pub id: String,
    #[serde(rename = "firstName")]
    pub first_name: Option<String>,
    #[serde(rename = "lastName")]
    pub last_name: Option<String>,
    pub username: Option<String>,
    pub email: Option<String>,
    #[serde(rename = "telegramId")]
    pub telegram_id: Option<String>,
}

/// Auth error response from backend
#[allow(dead_code)]
#[derive(Debug, Deserialize)]
pub struct AuthErrorResponse {
    pub success: bool,
    pub error: Option<String>,
}

/// Auth state that can be emitted to frontend
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AuthState {
    pub is_authenticated: bool,
    pub user: Option<User>,
}

use super::types::{BrowserAction, ResolvedBackend};
use serde_json::Value;

/// Parse a JSON `args` object into a typed `BrowserAction`.
pub(crate) fn parse_browser_action(
    action_str: &str,
    args: &Value,
) -> anyhow::Result<BrowserAction> {
    match action_str {
        "open" => {
            let url = args
                .get("url")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("Missing 'url' for open action"))?;
            Ok(BrowserAction::Open { url: url.into() })
        }
        "snapshot" => Ok(BrowserAction::Snapshot {
            interactive_only: args
                .get("interactive_only")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(true),
            compact: args
                .get("compact")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(true),
            depth: args
                .get("depth")
                .and_then(serde_json::Value::as_u64)
                .map(|d| u32::try_from(d).unwrap_or(u32::MAX)),
        }),
        "click" => {
            let selector = args
                .get("selector")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("Missing 'selector' for click"))?;
            Ok(BrowserAction::Click {
                selector: selector.into(),
            })
        }
        "fill" => {
            let selector = args
                .get("selector")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("Missing 'selector' for fill"))?;
            let value = args
                .get("value")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("Missing 'value' for fill"))?;
            Ok(BrowserAction::Fill {
                selector: selector.into(),
                value: value.into(),
            })
        }
        "type" => {
            let selector = args
                .get("selector")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("Missing 'selector' for type"))?;
            let text = args
                .get("text")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("Missing 'text' for type"))?;
            Ok(BrowserAction::Type {
                selector: selector.into(),
                text: text.into(),
            })
        }
        "get_text" => {
            let selector = args
                .get("selector")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("Missing 'selector' for get_text"))?;
            Ok(BrowserAction::GetText {
                selector: selector.into(),
            })
        }
        "get_title" => Ok(BrowserAction::GetTitle),
        "get_url" => Ok(BrowserAction::GetUrl),
        "screenshot" => Ok(BrowserAction::Screenshot {
            path: args.get("path").and_then(|v| v.as_str()).map(String::from),
            full_page: args
                .get("full_page")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false),
        }),
        "wait" => Ok(BrowserAction::Wait {
            selector: args
                .get("selector")
                .and_then(|v| v.as_str())
                .map(String::from),
            ms: args.get("ms").and_then(serde_json::Value::as_u64),
            text: args.get("text").and_then(|v| v.as_str()).map(String::from),
        }),
        "press" => {
            let key = args
                .get("key")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("Missing 'key' for press"))?;
            Ok(BrowserAction::Press { key: key.into() })
        }
        "hover" => {
            let selector = args
                .get("selector")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("Missing 'selector' for hover"))?;
            Ok(BrowserAction::Hover {
                selector: selector.into(),
            })
        }
        "scroll" => {
            let direction = args
                .get("direction")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("Missing 'direction' for scroll"))?;
            Ok(BrowserAction::Scroll {
                direction: direction.into(),
                pixels: args
                    .get("pixels")
                    .and_then(serde_json::Value::as_u64)
                    .map(|p| u32::try_from(p).unwrap_or(u32::MAX)),
            })
        }
        "is_visible" => {
            let selector = args
                .get("selector")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("Missing 'selector' for is_visible"))?;
            Ok(BrowserAction::IsVisible {
                selector: selector.into(),
            })
        }
        "close" => Ok(BrowserAction::Close),
        "find" => {
            let by = args
                .get("by")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("Missing 'by' for find"))?;
            let value = args
                .get("value")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("Missing 'value' for find"))?;
            let action = args
                .get("find_action")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("Missing 'find_action' for find"))?;
            Ok(BrowserAction::Find {
                by: by.into(),
                value: value.into(),
                action: action.into(),
                fill_value: args
                    .get("fill_value")
                    .and_then(|v| v.as_str())
                    .map(String::from),
            })
        }
        other => anyhow::bail!("Unsupported browser action: {other}"),
    }
}

pub(crate) fn is_supported_browser_action(action: &str) -> bool {
    matches!(
        action,
        "open"
            | "snapshot"
            | "click"
            | "fill"
            | "type"
            | "get_text"
            | "get_title"
            | "get_url"
            | "screenshot"
            | "wait"
            | "press"
            | "hover"
            | "scroll"
            | "is_visible"
            | "close"
            | "find"
            | "mouse_move"
            | "mouse_click"
            | "mouse_drag"
            | "key_type"
            | "key_press"
            | "screen_capture"
    )
}

pub(crate) fn is_computer_use_only_action(action: &str) -> bool {
    matches!(
        action,
        "mouse_move" | "mouse_click" | "mouse_drag" | "key_type" | "key_press" | "screen_capture"
    )
}

pub(crate) fn backend_name(backend: ResolvedBackend) -> &'static str {
    match backend {
        ResolvedBackend::AgentBrowser => "agent_browser",
        ResolvedBackend::RustNative => "rust_native",
        ResolvedBackend::ComputerUse => "computer_use",
    }
}

pub(crate) fn unavailable_action_for_backend_error(
    action: &str,
    backend: ResolvedBackend,
) -> String {
    format!(
        "Action '{action}' is unavailable for backend '{}'",
        backend_name(backend)
    )
}

use regex::Regex;
use std::sync::LazyLock;

static SENSITIVE_KV_REGEX: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(r#"(?i)(token|api[_-]?key|password|secret|user[_-]?key|bearer|credential)["']?\s*[:=]\s*(?:"([^"]{8,})"|'([^']{8,})'|([a-zA-Z0-9_\-\.]{8,}))"#).unwrap()
});

/// Scrub credentials from tool output to prevent accidental exfiltration.
/// Replaces known credential patterns with a redacted placeholder while preserving
/// a small prefix for context.
pub(crate) fn scrub_credentials(input: &str) -> String {
    SENSITIVE_KV_REGEX
        .replace_all(input, |caps: &regex::Captures| {
            let full_match = &caps[0];
            let key = &caps[1];
            let val = caps
                .get(2)
                .or(caps.get(3))
                .or(caps.get(4))
                .map(|m| m.as_str())
                .unwrap_or("");

            // Preserve first 4 chars for context, then redact
            let prefix = if val.chars().count() > 4 {
                match val.char_indices().nth(4) {
                    Some((idx, _)) => &val[..idx],
                    None => val,
                }
            } else {
                ""
            };

            if full_match.contains(':') {
                if full_match.contains('"') {
                    format!("\"{}\": \"{}*[REDACTED]\"", key, prefix)
                } else {
                    format!("{}: {}*[REDACTED]", key, prefix)
                }
            } else if full_match.contains('=') {
                if full_match.contains('"') {
                    format!("{}=\"{}*[REDACTED]\"", key, prefix)
                } else {
                    format!("{}={}*[REDACTED]", key, prefix)
                }
            } else {
                format!("{}: {}*[REDACTED]", key, prefix)
            }
        })
        .to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_scrub_credentials_utf8() {
        // Regex requires at least 8 chars for the value
        // The [a-zA-Z0-9_\-\.]{8,} part of the regex does NOT match emoji
        // So we must use quotes to hit the "([^"]{8,})" part
        let input = "api_key: \"🦀🦀🦀🦀🦀🦀🦀🦀\"";
        let output = scrub_credentials(input);
        // Should preserve 4 crabs and then redact
        assert!(output.contains("🦀🦀🦀🦀*[REDACTED]"));
    }

    #[test]
    fn test_scrub_credentials_short_val() {
        let input = "api_key: 12345678";
        let output = scrub_credentials(input);
        assert!(output.contains("api_key: 1234*[REDACTED]"));
    }
}

import { getBackendUrl } from '../backendUrl';
import { getClientVersionHeaders } from '../clientVersionHeaders';
import { callCoreRpc } from '../coreRpcClient';

const EMAIL_MAGIC_LINK_TIMEOUT_MS = 15_000;

/**
 * Send a magic-link email for email-based login.
 * POST /auth/email/send-link
 * @param email - The user's email address.
 * @param frontendRedirectUri - Where the backend should redirect after verification
 *   (e.g. "openhuman://" for desktop, or the web app origin for web).
 */
export async function sendEmailMagicLink(
  email: string,
  frontendRedirectUri: string,
  timeoutMs = EMAIL_MAGIC_LINK_TIMEOUT_MS
): Promise<void> {
  const backendUrl = await getBackendUrl();
  const controller = new AbortController();
  const timeoutId = window.setTimeout(() => controller.abort(), timeoutMs);

  try {
    const versionHeaders = await getClientVersionHeaders();
    const response = await fetch(`${backendUrl}/auth/email/send-link`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...versionHeaders },
      body: JSON.stringify({ email, frontendRedirectUri }),
      signal: controller.signal,
    });
    if (!response.ok) {
      const body = (await response.json().catch(() => ({}))) as { error?: string };
      throw new Error(body.error ?? `Failed to send magic link (${response.status})`);
    }
  } catch (error) {
    if (
      (error instanceof DOMException && error.name === 'AbortError') ||
      (error instanceof Error && error.name === 'AbortError')
    ) {
      throw new Error('Request timed out. Please try again.');
    }
    throw error;
  } finally {
    window.clearTimeout(timeoutId);
  }
}

/**
 * Consume a verified login token and return the JWT.
 * Works for both Telegram and OAuth login tokens.
 * POST /telegram/login-tokens/:token/consume (no auth required)
 */
export async function consumeLoginToken(loginToken: string): Promise<string> {
  const response = await callCoreRpc<{ result: { jwtToken: string } }>({
    method: 'openhuman.auth.consume_login_token',
    params: { loginToken },
  });
  const jwtToken = response.result?.jwtToken;
  if (!jwtToken) {
    throw new Error('Login token invalid or expired');
  }
  return jwtToken;
}
